    /**
     * Class representing worksheet autofilters.
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/ApiAutoFilter/
     */
    interface ApiAutoFilter {
        /**
         * Reapplies the AutoFilter to the worksheet using the existing filter criteria.
         *
         * This method corresponds to the Excel AutoFilter.ApplyFilter behavior: it does not change the currently defined filter conditions; it only reevaluates which rows should be visible based on the active filters. If no AutoFilter is defined for the worksheet, the method does nothing.
         *
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/ApplyFilter/
         */
        ApplyFilter(): void;
        /**
         * Returns a value that indicates whether the worksheet has an AutoFilter applied.
         *
         * @returns boolean
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/GetFilterMode/
         */
        GetFilterMode(): boolean;
        /**
         * Returns the array of ApiFilter objects that represents the filters applied to the AutoFilter range.
         *
         * @returns [ApiFilter](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/ApiFilter/)[]
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/GetFilters/
         */
        GetFilters(): ApiFilter[];
        /**
         * Returns the parent object for the AutoFilter — either the ApiWorksheet the filter is applied to, or the ApiListObject if the filter belongs to a table.
         *
         * @returns [ApiWorksheet](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiWorksheet/ApiWorksheet/) | [ApiListObject](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiListObject/ApiListObject/)
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/GetParent/
         */
        GetParent(): ApiWorksheet | ApiListObject;
        /**
         * Returns the ApiRange object that represents the AutoFilter range.
         *
         * @returns [ApiRange](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiRange/ApiRange/) | null
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/GetRange/
         */
        GetRange(): ApiRange | null;
        /**
         * Clears all filters and displays all rows in the AutoFilter range.
         *
         * This method corresponds to the Excel AutoFilter.ShowAllData behavior: it removes any active filtering from the worksheet while preserving the AutoFilter drop-downs on the header row. If no AutoFilter is defined for the worksheet, the method does nothing.
         *
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/Methods/ShowAllData/
         */
        ShowAllData(): void;
        /**
         * Returns a value that indicates whether the worksheet has an AutoFilter applied.
         */
        FilterMode: boolean;
        /**
         * Returns the array of ApiFilter objects that represents the filters applied to the range.
         */
        Filters: ApiFilter[];
        /**
         * Returns the ApiWorksheet object that contains the AutoFilter.
         */
        Parent: ApiWorksheet;
        /**
         * Returns the ApiRange object that represents the AutoFilter range; null if no AutoFilter is defined.
         */
        Range: ApiRange | null;
    }

