    /**
     * Class representing a single AutoFilter column.
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/ApiFilter/
     */
    interface ApiFilter {
        /**
         * Returns the first criteria associated with the filter for this column.
         *
         * @returns string | string[] | number | [XlDynamicFilterCriteria](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Enumeration/XlDynamicFilterCriteria/) | null
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/Methods/GetCriteria1/
         */
        GetCriteria1(): string | string[] | number | XlDynamicFilterCriteria | null;
        /**
         * Returns the second criteria associated with the filter for this column.
         *
         * @returns string | null
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/Methods/GetCriteria2/
         */
        GetCriteria2(): string | null;
        /**
         * Indicates whether any filter is applied on this column.
         *
         * The property is true when at least one of the following underlying structures is present for the column:
         *
         * - Filters
         * - CustomFiltersObj
         * - DynamicFilter
         * - ColorFilter
         * - Top10
         *
         * @returns boolean
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/Methods/GetOn/
         */
        GetOn(): boolean;
        /**
         * Returns the operator used for the filter on this column.
         *
         * @returns [XlAutoFilterOperator](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/Enumeration/XlAutoFilterOperator/) | null
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/Methods/GetOperator/
         */
        GetOperator(): XlAutoFilterOperator | null;
        /**
         * Returns the parent filters collection for this filter column.
         *
         * @returns [ApiAutoFilter](https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiAutoFilter/ApiAutoFilter/)
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiFilter/Methods/GetParent/
         */
        GetParent(): ApiAutoFilter;
        /**
         * Returns the first criteria associated with the filter.
         */
        Criteria1: string | string[] | number | XlDynamicFilterCriteria | null;
        /**
         * Returns the second criteria associated with the filter (used with xlAnd/xlOr).
         */
        Criteria2: string | null;
        /**
         * Indicates whether any filter is applied to this column.
         */
        On: boolean;
        /**
         * Returns the operator used for the filter on this column.
         */
        Operator: XlAutoFilterOperator | null;
        /**
         * Returns the parent filters collection for this filter column.
         */
        Parent: ApiAutoFilter;
    }

