        /**
         * Returns or sets the background color of the format condition.
         */
        FillColor: ApiColor | "No Fill";
        /**
         * Returns the font applied by the format condition.
         */
        Font: ApiFont | null;
        /**
         * Returns or sets the first formula used by the format condition.
         */
        Formula1: string;
        /**
         * Returns or sets the second formula used by the format condition.
         */
        Formula2: string;
        /**
         * Returns or sets the number format applied to a cell when the conditional formatting rule evaluates to true.
         */
        NumberFormat: string;
        /**
         * Returns the format condition operator.
         */
        Operator: XlFormatConditionOperator;
        /**
         * Returns the pivot table condition object.
         */
        PTCondition: PTCondition;
        /**
         * Returns the parent range object of the format condition.
         */
