        /**
         * Returns or sets the priority of the condition.
         */
        Priority: number;
        /**
         * Returns or sets the rank for top/bottom conditional formatting rules.
         */
        Rank: number;
        /**
         * Returns or sets the scope type for the format condition.
         */
        ScopeType: XlPivotConditionScope;
        /**
         * Returns or sets the number of standard deviations for average conditions.
         */
        StdDev: number;
        /**
         * Returns or sets whether subsequent conditional formatting rules should be evaluated when this rule evaluates to true.
         */
        StopIfTrue: boolean;
        /**
         * Returns or sets the text for text-based conditions.
         */
        Text: string;
        /**
         * Returns or sets the text operator for text-based conditions.
         */
        TextOperator: XlContainsOperator;
        /**
         * Returns the format condition type.
         */
        Type: XlFormatConditionType;
