    /**
     * Class representing a collection of pivot filters applied to a pivot field.
     *
     * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiPivotFilters/ApiPivotFilters/
     */
    interface ApiPivotFilters {
        /**
         * Adds a new filter to the pivot field.
         *
         * This method is VBA-compatible and follows the PivotFilters.Add signature from Excel VBA. Supports all major filter types including label filters, value filters, top/bottom filters, and date filters.
         *
         * @param filterType The type of filter to add. Must match VBA XlPivotFilterType enum values.
         * @param [dataField] The data field object to filter by. Required for value filters (xlValue* types) and top/bottom filters.
         * @param [value1] The first value for the filter condition. Required for comparison, between, and top/bottom count filters.
         * @param [value2] The second value for "Between" conditions (xlCaptionIsBetween, xlCaptionIsNotBetween, xlValueIsBetween).
         * @param [wholeDayFilter] Specifies whether to filter by whole day for date filters. Reserved for future use, currently not implemented.
         * @see https://api.onlyoffice.com/docs/office-api/usage-api/spreadsheet-api/ApiPivotFilters/Methods/Add/
         */
        Add(filterType: XlPivotFilterType, dataField?: ApiPivotDataField, value1?: string | number | Date, value2?: string | number | Date, wholeDayFilter?: boolean): void;
    }

